"""Small parsers and builders shared by the book commands."""

import re

from tallybook.cli.framework import Command
from tallybook.dates import format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict
from tallybook.model import Posting, Transaction
from tallybook.money import Money

_WHOLE = re.compile(r"-?[0-9]{1,18}")
_BLANKS = re.compile(r"[ \t]+")


def command(registry, words, usage, summary, positionals=(), options=None, required=(), aliases=None):
    """Decorator registering a handler as a Command in ``registry``."""

    def register(handler):
        registry.append(
            Command(
                words=tuple(words.split()),
                usage=usage,
                summary=summary,
                handler=handler,
                positionals=tuple(positionals),
                options=dict(options or {}),
                required=tuple(required),
                aliases=dict(aliases or {}),
            )
        )
        return handler

    return register


def whole_number(text, what, negative=False):
    """Read a whole number argument (at most 18 digits, a minus sign only where allowed)."""
    if not _WHOLE.fullmatch(text) or (text.startswith("-") and not negative):
        raise ValidationError("%s: not a whole number: %s" % (what, text))
    return int(text)


def opt_date(opts, name, default=None):
    """The date given in option ``name``, else ``default``."""
    if name in opts:
        return parse_date(opts[name])
    return default


def fd(value):
    """A date as text, or None."""
    return None if value is None else format_date(value)


def parse_posting(text):
    """Read ``ACCOUNT [AMOUNT CUR] [; note]`` into a Posting."""
    head, _, note = text.partition(";")
    parts = _BLANKS.split(head.strip(" \t"))
    if parts == [""]:
        raise ValidationError("invalid posting: %r" % text)
    if len(parts) == 1:
        return Posting(parts[0], None, note.strip())
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note.strip())
    raise ValidationError("invalid posting %r: expected ACCOUNT or ACCOUNT AMOUNT CURRENCY, then an optional ; note" % text)


def build_transaction(opts, payee, on):
    """The transaction described by ``--narration/--flag/--tag/--posting`` options."""
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(
        on,
        payee,
        opts.get("--narration", ""),
        postings,
        tuple(opts.get("--tag", [])),
        opts.get("--flag", "*"),
    )


def account_dict(account):
    """The JSON object of an account."""
    return {
        "path": account.path,
        "type": account.type,
        "currency": account.currency,
        "opened": fd(account.opened),
        "closed": fd(account.closed),
        "note": account.note,
    }


def money_list(balance):
    """A balance dict (currency -> Money) as a list of money objects in currency order."""
    return [money_to_dict(balance[c]) for c in sorted(balance)]

