"""Book commands: init, db, serve, account, tx, query, export, journal."""

import os

from tallybook.cli.helpers import (
    account_dict,
    build_transaction,
    command,
    fd,
    money_list,
    opt_date,
    whole_number,
)
from tallybook.cli.views import transactions_json, tx_table
from tallybook.errors import ValidationError
from tallybook.export import to_json, transaction_to_dict, transactions_to_csv
from tallybook.journal import format_journal, format_transaction, parse_journal
from tallybook.storage import LATEST_VERSION, Store

COMMANDS = []


def _reg(*args, **kwargs):
    return command(COMMANDS, *args, **kwargs)


@_reg("init", "init", "create the book, or migrate an older one")
def init(ctx, args, opts):
    path = ctx.db_path
    before = None
    if os.path.lexists(path):
        before = 0 if os.path.isfile(path) and os.path.getsize(path) == 0 else None
    existed = os.path.lexists(path)
    with Store.open(path, create=True) as store:
        if not existed:
            ctx.out("created %s (version %d)\n" % (path, store.version))
        elif before == 0:
            ctx.out("migrated %s from version 0 to %d\n" % (path, store.version))
        elif store.version < LATEST_VERSION:
            old = store.version
            store.migrate()
            ctx.out("migrated %s from version %d to %d\n" % (path, old, store.version))
        else:
            ctx.out("%s is up to date (version %d)\n" % (path, store.version))


@_reg("db version", "db version", "print the schema version")
def db_version(ctx, args, opts):
    with ctx.open_store() as store:
        ctx.out("%d\n" % store.version)


@_reg("db migrate", "db migrate", "apply the missing schema migrations")
def db_migrate(ctx, args, opts):
    with ctx.open_store() as store:
        applied = store.migrate()
        if not applied:
            ctx.out("database is up to date (version %d)\n" % store.version)
        for version in applied:
            ctx.out("applied version %d\n" % version)


@_reg("db info", "db info [--json]", "show path, version and row counts", options={"--json": "flag"})
def db_info(ctx, args, opts):
    with ctx.open_store() as store:
        info = store.info()
    if "--json" in opts:
        ctx.out(to_json(info))
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.out("%s: %s\n" % (key, info[key]))


@_reg("db check", "db check", "look for damage in the book")
def db_check(ctx, args, opts):
    with ctx.open_store() as store:
        problems = store.check()
    if not problems:
        ctx.out("ok\n")
        return
    ctx.out("".join(p + "\n" for p in problems))
    ctx.exit_status = 1


@_reg("db backup", "db backup DEST", "copy the book to a new file", positionals=("DEST",))
def db_backup(ctx, args, opts):
    with ctx.open_store() as store:
