        store.delete_transaction(tx_id)
    ctx.out("deleted transaction %d\n" % tx_id)


@_reg(
    "query",
    "query QUERY [--limit N] [--offset N] [--json] [--count]",
    "find transactions with the query language",
    positionals=("QUERY",),
    options={"--limit": "value", "--offset": "value", "--json": "flag", "--count": "flag"},
)
def query(ctx, args, opts):
