    return format_journal(store.journal())


@_reg(
    "export",
    "export [--format csv|json|journal] [--query QUERY]",
    "export transactions as CSV, JSON or the whole book as journal text",
    options={"--format": "value", "--query": "value"},
)
def export(ctx, args, opts):
    fmt = opts.get("--format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise ValidationError("unknown export format: %s (use csv, json or journal)" % fmt)
    if fmt == "journal" and "--query" in opts:
