    from tallybook.errors import ParseError

    name = ctx.stdin_name if args[0] == "-" else args[0]
    text = ctx.read_text(args[0], "journal")
    try:
        journal = parse_journal(text)
    except ParseError as exc:
        exc.message = "%s: %s" % (name, exc.message)
        raise
    with ctx.open_store() as store:
        store.load_journal(journal)
    ctx.out(
