        info = store.info()
    if "--json" in opts:
        ctx.out(to_json(info))
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.out("%s: %s\n" % (key, info[key]))


@_reg("db check", "db check", "look for damage in the book")
def db_check(ctx, args, opts):
    with ctx.open_store() as store:
        problems = store.check()
    if not problems:
        ctx.out("ok\n")
        return
    ctx.out("".join(p + "\n" for p in problems))
    ctx.exit_status = 1


@_reg("db backup", "db backup DEST", "copy the book to a new file", positionals=("DEST",))
def db_backup(ctx, args, opts):
    with ctx.open_store() as store:
        store.backup(args[0])
    ctx.out("backed up to %s\n" % args[0])


@_reg(
    "serve",
    "serve [--host HOST] [--port N]",
    "serve the book over HTTP",
    options={"--host": "value", "--port": "value"},
)
def serve(ctx, args, opts):
    host = opts.get("--host", "127.0.0.1")
    port = whole_number(opts["--port"], "--port") if "--port" in opts else 8765
    if port > 65535:
        raise ValidationError("--port: port out of range: %d" % port)
    with ctx.open_store() as store:
        store.info()
    from tallybook.api.server import serve as run_server

    status = run_server(ctx.db_path, host=host, port=port, today=ctx.today_arg)
    if status:
        ctx.exit_status = status


@_reg(
    "account add",
    "account add PATH [--currency CUR] [--open DATE] [--note TEXT]",
    "add an account",
    positionals=("PATH",),
    options={"--currency": "value", "--open": "value", "--note": "value"},
)
def account_add(ctx, args, opts):
    opened = opt_date(opts, "--open")
    with ctx.open_store() as store:
        store.add_account(args[0], currency=opts.get("--currency"), opened=opened, note=opts.get("--note", ""))
    ctx.out("added account %s\n" % args[0])


@_reg(
    "account list",
    "account list [--type TYPE] [--under PATH] [--currency CUR] [--open-only] [--json]",
    "list accounts",
    options={"--type": "value", "--under": "value", "--currency": "value", "--open-only": "flag", "--json": "flag"},
)
def account_list(ctx, args, opts):
    from tallybook.export import render_table

    with ctx.open_store() as store:
        accounts = store.accounts(
            type=opts.get("--type"),
            under=opts.get("--under"),
            currency=opts.get("--currency"),
            include_closed="--open-only" not in opts,
        )
    if "--json" in opts:
        ctx.out(to_json([account_dict(a) for a in accounts]))
    elif accounts:
        rows = [[a.path, a.type, a.currency, fd(a.opened), fd(a.closed), a.note] for a in accounts]
        ctx.out(render_table(["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows))


@_reg(
    "account show",
    "account show PATH [--json]",
    "show one account and its balance",
    positionals=("PATH",),
    options={"--json": "flag"},
)
def account_show(ctx, args, opts):
    with ctx.open_store() as store:
        account = store.get_account(args[0])
        balance = store.ledger().balance(account.path)
    if "--json" in opts:
        data = account_dict(account)
        data["balance"] = money_list(balance)
        ctx.out(to_json(data))
        return
    note = "note: %s" % account.note if account.note else "note:"
    ctx.out("path: %s\n" % account.path)
    ctx.out("type: %s\n" % account.type)
    ctx.out("currency: %s\n" % (account.currency or "any"))
    ctx.out("opened: %s\n" % (fd(account.opened) or "none"))
    ctx.out("closed: %s\n" % (fd(account.closed) or "none"))
    ctx.out(note + "\n")
    ctx.out("balance: %s\n" % (", ".join(str(balance[c]) for c in sorted(balance)) or "none"))


@_reg(
    "account close",
    "account close PATH [--on DATE]",
    "close an account",
    positionals=("PATH",),
    options={"--on": "value"},
)
def account_close(ctx, args, opts):
    on = opt_date(opts, "--on", ctx.today)
    with ctx.open_store() as store:
        store.close_account(args[0], on)
    ctx.out("closed account %s on %s\n" % (args[0], fd(on)))


@_reg(
    "tx add",
    "tx add PAYEE [--date DATE] [--narration TEXT] [--flag F] [--tag TAG]... [-p POSTING]... [--json]",
    "add a transaction",
    positionals=("PAYEE",),
    options={
        "--date": "value",
        "--narration": "value",
        "--flag": "value",
        "--tag": "multi",
        "--posting": "multi",
        "--json": "flag",
    },
    aliases={"-p": "--posting"},
)
def tx_add(ctx, args, opts):
    tx = build_transaction(opts, args[0], opt_date(opts, "--date", ctx.today))
    with ctx.open_store() as store:
        stored = store.add_transaction(tx)
    if "--json" in opts:
        ctx.out(to_json(transaction_to_dict(stored)))
    else:
        ctx.out("added transaction %d\n" % stored.id)


def _listing(ctx, query, opts):
    limit = whole_number(opts["--limit"], "--limit") if "--limit" in opts else None
    offset = whole_number(opts["--offset"], "--offset") if "--offset" in opts else 0
    with ctx.open_store() as store:
        txs = store.transactions(query, limit, offset)
    ctx.out(transactions_json(txs) if "--json" in opts else tx_table(txs))


@_reg(
    "tx list",
    "tx list [--query QUERY] [--limit N] [--offset N] [--json]",
    "list transactions",
    options={"--query": "value", "--limit": "value", "--offset": "value", "--json": "flag"},
)
def tx_list(ctx, args, opts):
    _listing(ctx, opts.get("--query"), opts)


@_reg(
    "tx show",
    "tx show ID [--json]",
    "show one transaction",
    positionals=("ID",),
    options={"--json": "flag"},
)
def tx_show(ctx, args, opts):
    tx_id = whole_number(args[0], "transaction id")
    with ctx.open_store() as store:
        tx = store.get_transaction(tx_id)
    if "--json" in opts:
        ctx.out(to_json(transaction_to_dict(tx)))
    else:
        ctx.out("; id %d\n" % tx.id + format_transaction(tx))


@_reg("tx delete", "tx delete ID", "delete a transaction", positionals=("ID",))
def tx_delete(ctx, args, opts):
    tx_id = whole_number(args[0], "transaction id")
    with ctx.open_store() as store:
        store.delete_transaction(tx_id)
    ctx.out("deleted transaction %d\n" % tx_id)


@_reg(
    "query",
    "query QUERY [--limit N] [--offset N] [--json] [--count]",
    "find transactions with the query language",
    positionals=("QUERY",),
    options={"--limit": "value", "--offset": "value", "--json": "flag", "--count": "flag"},
)
def query(ctx, args, opts):
    if "--count" in opts:
        with ctx.open_store() as store:
            ctx.out("%d\n" % store.count_transactions(args[0]))
        return
    _listing(ctx, args[0], opts)


def _journal_text(store):
    return format_journal(store.journal())


@_reg(
    "export",
    "export [--format csv|json|journal] [--query QUERY]",
    "export transactions as CSV, JSON or the whole book as journal text",
    options={"--format": "value", "--query": "value"},
)
def export(ctx, args, opts):
    fmt = opts.get("--format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise ValidationError("unknown export format: %s (use csv, json or journal)" % fmt)
    if fmt == "journal" and "--query" in opts:
        raise ValidationError("--query cannot be used with --format journal")
    with ctx.open_store() as store:
        if fmt == "journal":
            ctx.out(_journal_text(store))
            return
        txs = store.transactions(opts.get("--query"))
    ctx.out(transactions_to_csv(txs) if fmt == "csv" else transactions_json(txs))


@_reg("journal export", "journal export", "print the whole book as journal text")
def journal_export(ctx, args, opts):
    with ctx.open_store() as store:
        ctx.out(_journal_text(store))


@_reg("journal import", "journal import FILE", "add a journal file to the book", positionals=("FILE",))
def journal_import(ctx, args, opts):
    from tallybook.errors import ParseError

    name = ctx.stdin_name if args[0] == "-" else args[0]
    text = ctx.read_text(args[0], "journal")
    try:
        journal = parse_journal(text)
    except ParseError as exc:
        exc.message = "%s: %s" % (name, exc.message)
        raise
    with ctx.open_store() as store:
        store.load_journal(journal)
    ctx.out(
        "imported %d accounts, %d rates, %d transactions\n"
        % (len(journal.accounts), len(journal.rates), len(journal.transactions))
    )

