"""Data commands: import, profile, rules, rate, budget, recurring, report."""

from tallybook.budgets import Budget, budget_status
from tallybook.cli.context import UsageError
from tallybook.cli.helpers import build_transaction, command, fd, opt_date, whole_number
from tallybook.cli.views import (
    budget_lines_json,
    budget_table,
    month_of,
    run_report,
)
from tallybook.dates import Period, parse_date
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_json, transaction_to_dict
from tallybook.money import Money
from tallybook.recurring import Recurring

COMMANDS = []


def _reg(*args, **kwargs):
    return command(COMMANDS, *args, **kwargs)


def _with_newline(text):
    return text if text == "" or text.endswith("\n") else text + "\n"


@_reg(
    "import",
    "import FILE (--profile NAME | --profile-file FILE) [--no-rules]",
    "import a bank CSV statement",
    positionals=("FILE",),
    options={"--profile": "value", "--profile-file": "value", "--no-rules": "flag"},
)
def import_(ctx, args, opts):
    if ("--profile" in opts) == ("--profile-file" in opts):
        raise UsageError("give exactly one of --profile and --profile-file")
    text = ctx.read_text(args[0], "statement")
    profile_text = ctx.read_text(opts["--profile-file"], "profile") if "--profile-file" in opts else None
    with ctx.open_store() as store:
        if profile_text is None:
            profile_text = store.profile_text(opts["--profile"])
        outcome = store.import_csv(text, profile_text, apply_rules="--no-rules" not in opts)
    if outcome.errors:
        lines = ["%d rows could not be imported, nothing was imported" % len(outcome.errors)]
        lines.extend("row %d: %s" % (row, message) for row, message in outcome.errors)
        raise ValidationError("\n".join(lines))
    ctx.out("imported %d transactions, %d duplicates\n" % (len(outcome.added), len(outcome.duplicates)))


@_reg("profile add", "profile add NAME FILE", "store an import profile", positionals=("NAME", "FILE"))
def profile_add(ctx, args, opts):
    text = ctx.read_text(args[1], "profile")
    with ctx.open_store() as store:
        store.set_profile(args[0], text)
    ctx.out("stored profile %s\n" % args[0])


@_reg("profile list", "profile list [--json]", "list stored profiles", options={"--json": "flag"})
def profile_list(ctx, args, opts):
    with ctx.open_store() as store:
        names = store.profiles()
    if "--json" in opts:
        ctx.out(to_json(list(names)))
    else:
        ctx.out("".join(n + "\n" for n in names))


@_reg("profile show", "profile show NAME", "print a stored profile", positionals=("NAME",))
def profile_show(ctx, args, opts):
    with ctx.open_store() as store:
        ctx.out(_with_newline(store.profile_text(args[0])))


@_reg("profile remove", "profile remove NAME", "remove a stored profile", positionals=("NAME",))
def profile_remove(ctx, args, opts):
    with ctx.open_store() as store:
        store.remove_profile(args[0])
    ctx.out("removed profile %s\n" % args[0])


@_reg("rules set", "rules set FILE", "store the categorisation rules", positionals=("FILE",))
def rules_set(ctx, args, opts):
    text = ctx.read_text(args[0], "rules")
    with ctx.open_store() as store:
        store.set_rules(text)
        count = len(store.rules())
    ctx.out("stored %d rules\n" % count)


@_reg("rules show", "rules show", "print the stored rules")
def rules_show(ctx, args, opts):
    with ctx.open_store() as store:
        ctx.out(_with_newline(store.rules_text()))


@_reg(
    "rate set",
    "rate set FROM TO RATE [--on DATE]",
    "record an exchange rate",
    positionals=("FROM", "TO", "RATE"),
    options={"--on": "value"},
)
def rate_set(ctx, args, opts):
    on = opt_date(opts, "--on", ctx.today)
    with ctx.open_store() as store:
        store.set_rate(args[0], args[1], args[2], on)
    ctx.out("set 1 %s = %s %s on %s\n" % (args[0], args[2], args[1], fd(on)))


@_reg("rate list", "rate list [--json]", "list exchange rates", options={"--json": "flag"})
def rate_list(ctx, args, opts):
    with ctx.open_store() as store:
        rows = store.rate_rows()
    if "--json" in opts:
        ctx.out(to_json([{"from": s, "to": d, "date": fd(on), "rate": r} for s, d, on, r in rows]))
    elif rows:
        ctx.out(render_table(["From", "To", "Date", "Rate"], [[s, d, fd(on), r] for s, d, on, r in rows], "lllr"))


@_reg(
    "rate remove",
    "rate remove FROM TO [--on DATE]",
    "remove an exchange rate",
    positionals=("FROM", "TO"),
    options={"--on": "value"},
)
def rate_remove(ctx, args, opts):
    on = opt_date(opts, "--on", ctx.today)
    with ctx.open_store() as store:
        store.remove_rate(args[0], args[1], on)
    ctx.out("removed rate %s -> %s on %s\n" % (args[0], args[1], fd(on)))


@_reg(
    "budget add",
    "budget add PATTERN AMOUNT [--per KIND] [--start DATE]",
    "add a budget",
    positionals=("PATTERN", "AMOUNT"),
    options={"--per": "value", "--start": "value"},
)
def budget_add(ctx, args, opts):
    per = opts.get("--per", "month")
    budget = Budget(args[0], per, Money.parse(args[1]), opt_date(opts, "--start", ctx.today))
    with ctx.open_store() as store:
        store.add_budget(budget)
    ctx.out("added budget %s %s per %s\n" % (args[0], budget.amount, per))


@_reg("budget list", "budget list [--json]", "list budgets", options={"--json": "flag"})
def budget_list(ctx, args, opts):
    with ctx.open_store() as store:
        budgets = store.budgets()
    if "--json" in opts:
        ctx.out(
            to_json(
                [
                    {
                        "pattern": b.pattern,
                        "period_kind": b.period_kind,
                        "amount": money_to_dict(b.amount),
                        "start": fd(b.start),
                    }
                    for b in budgets
                ]
            )
        )
    elif budgets:
        rows = [[b.pattern, b.period_kind, str(b.amount), fd(b.start)] for b in budgets]
        ctx.out(render_table(["Pattern", "Per", "Amount", "Start"], rows, "llrl"))


@_reg(
    "budget remove",
    "budget remove PATTERN [--per KIND]",
    "remove a budget",
    positionals=("PATTERN",),
    options={"--per": "value"},
)
def budget_remove(ctx, args, opts):
    per = opts.get("--per", "month")
    with ctx.open_store() as store:
        store.remove_budget(args[0], per)
    ctx.out("removed budget %s per %s\n" % (args[0], per))


@_reg(
    "budget status",
    "budget status [--period PERIOD] [--json]",
    "show how the budgets are doing",
    options={"--period": "value", "--json": "flag"},
)
def budget_status_cmd(ctx, args, opts):
    period = Period.parse(opts["--period"]) if "--period" in opts else month_of(ctx.today)
    with ctx.open_store() as store:
        lines = budget_status(store.budgets(), store.ledger(), period)
    ctx.out(budget_lines_json(lines) if "--json" in opts else budget_table(lines))


@_reg(
    "recurring add",
    "recurring add NAME SCHEDULE PAYEE [--start DATE] [--end DATE] [--count N] [--narration TEXT] "
    "[--flag F] [--tag TAG]... [-p POSTING]...",
    "add a recurring transaction",
    positionals=("NAME", "SCHEDULE", "PAYEE"),
    options={
        "--start": "value",
        "--end": "value",
        "--count": "value",
        "--narration": "value",
        "--flag": "value",
        "--tag": "multi",
        "--posting": "multi",
    },
    aliases={"-p": "--posting"},
)
def recurring_add(ctx, args, opts):
    start = opt_date(opts, "--start", ctx.today)
    end = opt_date(opts, "--end")
    count = whole_number(opts["--count"], "--count") if "--count" in opts else None
    template = build_transaction(opts, args[2], start)
    rec = Recurring(args[0], args[1], template, start, end, count)
    with ctx.open_store() as store:
        store.add_recurring(rec)
    ctx.out("added recurring %s\n" % args[0])


def _recurring_dict(rec, through):
    template = transaction_to_dict(rec.template)
    return {
        "name": rec.name,
        "schedule": str(rec.schedule),
        "start": fd(rec.start),
        "end": fd(rec.end),
        "count": rec.count,
        "materialized_through": fd(through),
        "template": {
            "payee": template["payee"],
            "narration": template["narration"],
            "flag": template["flag"],
            "tags": template["tags"],
            "postings": template["postings"],
        },
    }


@_reg("recurring list", "recurring list [--json]", "list recurring transactions", options={"--json": "flag"})
def recurring_list(ctx, args, opts):
    with ctx.open_store() as store:
        items = [(rec, store.materialized_through(rec.name)) for rec in store.recurring()]
    if "--json" in opts:
        ctx.out(to_json([_recurring_dict(rec, through) for rec, through in items]))
    elif items:
        rows = [
            [
                rec.name,
                str(rec.schedule),
                fd(rec.start),
                fd(rec.end),
                rec.count,
                fd(through),
                rec.template.payee,
            ]
            for rec, through in items
        ]
        ctx.out(render_table(["Name", "Schedule", "Start", "End", "Count", "Through", "Payee"], rows))


@_reg("recurring remove", "recurring remove NAME", "remove a recurring transaction", positionals=("NAME",))
def recurring_remove(ctx, args, opts):
    with ctx.open_store() as store:
        store.remove_recurring(args[0])
    ctx.out("removed recurring %s\n" % args[0])


@_reg(
    "recurring materialize",
    "recurring materialize [--upto DATE] [--json]",
    "turn due recurring entries into transactions",
    options={"--upto": "value", "--json": "flag"},
)
def recurring_materialize(ctx, args, opts):
    upto = opt_date(opts, "--upto")
    with ctx.open_store() as store:
        created = store.materialize(upto=upto, today=ctx.today)
    if "--json" in opts:
        ctx.out(to_json([transaction_to_dict(tx) for tx in created]))
    else:
        ctx.out("created %d transactions\n" % len(created))


def _report_command(kind, usage, summary, extra_options, positionals=()):
    options = {"--json": "flag"}
    options.update(extra_options)

    def handler(ctx, args, opts):
        with ctx.open_store() as store:
            ledger = store.ledger()
        ctx.out(
            run_report(
                kind,
                ledger,
                account=args[0] if args else None,
                as_of=parse_date(opts["--as-of"]) if "--as-of" in opts else None,
                period=Period.parse(opts["--period"]) if "--period" in opts else None,
                convert=opts.get("--convert"),
                rollup="--rollup" in opts,
                today=ctx.today,
                as_json="--json" in opts,
            )
        )

    command(COMMANDS, "report " + kind, "report " + usage, summary, positionals, options)(handler)


_report_command(
    "trial-balance", "trial-balance [--as-of DATE] [--json]", "trial balance", {"--as-of": "value"}
)
_report_command(
    "balance-sheet",
    "balance-sheet [--as-of DATE] [--convert CUR] [--json]",
    "balance sheet",
    {"--as-of": "value", "--convert": "value"},
)
_report_command(
    "income-statement",
    "income-statement [--period PERIOD] [--convert CUR] [--json]",
    "income statement",
    {"--period": "value", "--convert": "value"},
)
_report_command("cashflow", "cashflow [--period PERIOD] [--json]", "cash flow", {"--period": "value"})
_report_command(
    "register",
    "register ACCOUNT [--period PERIOD] [--rollup] [--json]",
    "register of one account",
    {"--period": "value", "--rollup": "flag"},
    positionals=("ACCOUNT",),
)

