"""The tallybook command line: ``main(argv) -> int``."""

import os
import sys

from tallybook import __version__
from tallybook.cli.context import Context, UsageError
from tallybook.dates import parse_date
from tallybook.errors import TallybookError

HELP_FLAGS = ("-h", "--help")
GLOBAL_USAGE = "usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS and --options]\n"
TRY_HELP = "Try 'tallybook --help'."


class _Finished(Exception):
    """Output was produced and the run ends with status 0 (help, version)."""

    def __init__(self, text):
        Exception.__init__(self, text)
        self.text = text


def all_commands():
    """Every command of the program."""
    from tallybook.cli import calc, commands_book, commands_data

    return commands_book.COMMANDS + commands_data.COMMANDS + calc.COMMANDS


def _root_help(commands):
    lines = [
        GLOBAL_USAGE.rstrip("\n"),
        "",
